"use strict";(globalThis.webpackChunkdocs_that_speak=globalThis.webpackChunkdocs_that_speak||[]).push([[13],{4354(e,t,n){n.r(t),n.d(t,{assets:()=>c,contentTitle:()=>s,default:()=>d,frontMatter:()=>o,metadata:()=>i,toc:()=>h});const i=JSON.parse('{"id":"nextgen/invisible-architecture","title":"The Architecture No One Sees","description":"Nobody notices a good content structure. That is exactly the point.","source":"@site/docs/nextgen/invisible-architecture.md","sourceDirName":"nextgen","slug":"/nextgen/invisible-architecture","permalink":"/DocsThatSpeak/docs/nextgen/invisible-architecture","draft":false,"unlisted":false,"editUrl":"https://github.com/JKwrites-tech/DocsThatSpeak/edit/main/docs/nextgen/invisible-architecture.md","tags":[],"version":"current","sidebarPosition":4,"frontMatter":{"id":"invisible-architecture","title":"The Architecture No One Sees","sidebar_position":4},"sidebar":"nextgenSidebar","previous":{"title":"No One Reads Your Docs From the Top","permalink":"/DocsThatSpeak/docs/nextgen/no-one-reads-from-the-top"}}');var r=n(4848),a=n(8453);const o={id:"invisible-architecture",title:"The Architecture No One Sees",sidebar_position:4},s="The Architecture No One Sees",c={},h=[{value:"What a Content Model Actually Is",id:"what-a-content-model-actually-is",level:2},{value:"Why Mixing These Types Breaks Documentation",id:"why-mixing-these-types-breaks-documentation",level:2},{value:"Information Architecture at the Navigation Level",id:"information-architecture-at-the-navigation-level",level:2},{value:"The 43% Test",id:"the-43-test",level:2},{value:"A Practical Starting Point",id:"a-practical-starting-point",level:2}];function l(e){const t={em:"em",h1:"h1",h2:"h2",header:"header",hr:"hr",p:"p",strong:"strong",...(0,a.R)(),...e.components};return(0,r.jsxs)(r.Fragment,{children:[(0,r.jsx)(t.header,{children:(0,r.jsx)(t.h1,{id:"the-architecture-no-one-sees",children:"The Architecture No One Sees"})}),"\n",(0,r.jsx)(t.p,{children:"Nobody notices a good content structure. That is exactly the point."}),"\n",(0,r.jsx)(t.p,{children:"When information architecture is working, users find what they need quickly, move between related topics naturally, and never have the experience of feeling lost in a documentation set. They do not think about the structure \u2014 they just experience the result of it."}),"\n",(0,r.jsx)(t.p,{children:"When it fails, the opposite is true. Users click into a category and find the wrong thing. They search and land on a page that almost answers their question. They navigate to a section labelled with a term they don't use themselves. They give up and open a support ticket."}),"\n",(0,r.jsx)(t.p,{children:"The architecture was invisible in both cases. In the first, it was invisibly good. In the second, it was invisibly broken."}),"\n",(0,r.jsx)(t.hr,{}),"\n",(0,r.jsx)(t.h2,{id:"what-a-content-model-actually-is",children:"What a Content Model Actually Is"}),"\n",(0,r.jsx)(t.p,{children:"A content model is the decision about what types of content exist in a documentation set, what each type is responsible for, and how they relate to each other. It is the structural logic underneath every article \u2014 the reason a reference page looks different from a tutorial, and why that difference matters to the reader."}),"\n",(0,r.jsx)(t.p,{children:"The most widely used content model in technical documentation separates content into three types:"}),"\n",(0,r.jsxs)(t.p,{children:[(0,r.jsx)(t.strong,{children:"Concept topics"})," answer the question ",(0,r.jsx)(t.em,{children:"what is this?"})," They explain a feature, a system, or a principle. They do not contain procedures. A user reads a concept topic to understand something before they do anything."]}),"\n",(0,r.jsxs)(t.p,{children:[(0,r.jsx)(t.strong,{children:"Task topics"})," answer the question ",(0,r.jsx)(t.em,{children:"how do I do this?"})," They contain numbered steps, prerequisites, and expected results. They do not contain explanations of why things work the way they do \u2014 that belongs in a concept topic. A user reads a task topic when they are ready to act."]}),"\n",(0,r.jsxs)(t.p,{children:[(0,r.jsx)(t.strong,{children:"Reference topics"})," answer the question ",(0,r.jsx)(t.em,{children:"what are the exact details?"})," API parameters, error code definitions, configuration values, field descriptions. Dense, precise, non-narrative. A user consults a reference topic when they need a specific detail \u2014 they do not read it from top to bottom."]}),"\n",(0,r.jsx)(t.hr,{}),"\n",(0,r.jsx)(t.h2,{id:"why-mixing-these-types-breaks-documentation",children:"Why Mixing These Types Breaks Documentation"}),"\n",(0,r.jsx)(t.p,{children:"The most common structural failure in documentation is mixing topic types within a single article. A procedure that contains three paragraphs of background explanation halfway through. A concept article that ends with a set of steps. A reference page that includes a tutorial."}),"\n",(0,r.jsx)(t.p,{children:"The problem is not aesthetic. It is functional."}),"\n",(0,r.jsx)(t.p,{children:"When task and concept content are mixed, users completing a procedure have to skip over explanatory content to follow the steps. When concept and reference content are mixed, users looking for a specific detail have to scan through narrative text to find it. Every paragraph the user has to evaluate and discard costs them time and patience \u2014 and neither is in generous supply."}),"\n",(0,r.jsx)(t.p,{children:"Separating content by type does not mean treating every piece of information in isolation. Related concepts, tasks, and reference material link to each other. The separation ensures that each piece of content does one job well, and users can navigate to the depth they need without being forced through the depth they don't."}),"\n",(0,r.jsx)(t.hr,{}),"\n",(0,r.jsx)(t.h2,{id:"information-architecture-at-the-navigation-level",children:"Information Architecture at the Navigation Level"}),"\n",(0,r.jsx)(t.p,{children:"Content model governs what is inside an article. Information architecture governs how articles are organised, labelled, and connected at the navigation level \u2014 the categories, sidebar structure, and headings users encounter before they reach any content."}),"\n",(0,r.jsx)(t.p,{children:"The most important principle at this level is that labels should use the user's language, not the product team's language."}),"\n",(0,r.jsx)(t.p,{children:"Internal product terminology \u2014 feature names, module labels, architectural terms \u2014 is often the natural language for the documentation team, because the team lives inside the product. It is rarely the natural language for the user, who approaches the documentation from the outside with a task or a question in their head."}),"\n",(0,r.jsx)(t.p,{children:"A navigation structure built on internal terminology forces users to translate before they can navigate. The cognitive overhead is small for any single step, but across a documentation set it accumulates into the experience of documentation that is technically complete but practically hard to use."}),"\n",(0,r.jsx)(t.hr,{}),"\n",(0,r.jsx)(t.h2,{id:"the-43-test",children:"The 43% Test"}),"\n",(0,r.jsx)(t.p,{children:"A redesigned information architecture across a documentation set for a major enterprise product reduced time-to-task by 43%. That number did not come from better writing. The prose in most of the articles was largely unchanged. It came from reorganising the navigation, relabelling categories in user language, and restructuring article-level headings as questions rather than topics."}),"\n",(0,r.jsx)(t.p,{children:"Users could find things faster because the architecture met them where they were \u2014 in the language of their task \u2014 rather than asking them to find their way into the language of the product."}),"\n",(0,r.jsx)(t.p,{children:"That is the work of information architecture. It happens before the first word of any article is written, and it shapes whether every article in the documentation set will be found."}),"\n",(0,r.jsx)(t.hr,{}),"\n",(0,r.jsx)(t.h2,{id:"a-practical-starting-point",children:"A Practical Starting Point"}),"\n",(0,r.jsx)(t.p,{children:"If you are building a documentation architecture from scratch or restructuring an existing one, start with this exercise before touching any content."}),"\n",(0,r.jsx)(t.p,{children:"Write down the ten questions your users ask most frequently \u2014 from support tickets, search queries, or direct user research. These are the entry points to your documentation. Now look at your current navigation and ask: if a user with one of these questions arrived at the top level of your documentation, what path would they take, and would it lead them to the right answer in under three clicks?"}),"\n",(0,r.jsx)(t.p,{children:"If the answer is no for most of the ten questions, your architecture is not serving your users \u2014 regardless of how good the content inside it is."}),"\n",(0,r.jsx)(t.p,{children:"The architecture no one sees is the reason good content gets found or doesn't. It is worth the time to get right before the content is written, not after."})]})}function d(e={}){const{wrapper:t}={...(0,a.R)(),...e.components};return t?(0,r.jsx)(t,{...e,children:(0,r.jsx)(l,{...e})}):l(e)}},8453(e,t,n){n.d(t,{R:()=>o,x:()=>s});var i=n(6540);const r={},a=i.createContext(r);function o(e){const t=i.useContext(a);return i.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function s(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(r):e.components||r:o(e.components),i.createElement(a.Provider,{value:t},e.children)}}}]);